import json
with open('baseline-packages.json') as f: baseline=json.load(f)
with open('after-cpm-packages.json') as f: after=json.load(f)

def extract(data):
    result={}
    for p in data.get('projects',[]):
        name=p['path'].split('/')[-1]
        for fw in p.get('frameworks',[]):
            for pkg in fw.get('topLevelPackages',[]):
                key=(name,pkg['id'])
                result[key]=pkg.get('resolvedVersion',pkg.get('requestedVersion','?'))
    return result

b=extract(baseline)
a=extract(after)
print('CHANGES:')
for k in sorted(set(list(b.keys())+list(a.keys()))):
    bv=b.get(k,'(missing)')
    av=a.get(k,'(missing)')
    if bv!=av:
        print(f'  {k[0]} | {k[1]}: {bv} -> {av}')
print('UNCHANGED:')
for k in sorted(b.keys()):
    if b.get(k)==a.get(k):
        print(f'  {k[0]} | {k[1]}: {b[k]}')
"

